library;

import 'dart:io';

import 'package:test/test.dart';
import 'package:zuraffa_ffi_workspace/tdd/001-zuraffa-7-family-alignment/a2_subject.dart' as subject;

void main() {
  group('A2 (AC-2)', () {
    test('A2 — all five family packages resolve through one pub workspace, with one shared lockfile and one shared package configuration.', () {
      final Object? result = (() {
        try {
          subject.subject_a2();
          return null;
        } on UnimplementedError catch (error) {
          return error;
        }
      })();
      expect(result, isNot(isA<UnimplementedError>()));
      // The observable outcome of the scenario: the family resolves through
      // one workspace — no stray lockfile, no stray package configuration.
      expect(subject.subject_a2(), isEmpty);
    });

    test('A2 — a workspace that is split, unlisted, or missing its lockfile is reported', () {
      final root = Directory.systemTemp.createTempSync('zuraffa_ffi_workspace');
      addTearDown(() => root.deleteSync(recursive: true));

      // A root pubspec without a `workspace:` block that lists only some of
      // the members, no shared lockfile, and one member that carries its own
      // lockfile and package configuration.
      File('${root.path}/pubspec.yaml').writeAsStringSync('''
name: broken_workspace
publish_to: none
''');
      final stray = Directory('${root.path}/packages/zuraffa_ffi_macos')
        ..createSync(recursive: true);
      File('${stray.path}/pubspec.lock').writeAsStringSync('# stray\n');
      Directory('${stray.path}/.dart_tool').createSync(recursive: true);
      File('${stray.path}/.dart_tool/package_config.json')
          .writeAsStringSync('{}');

      final violations = subject.subject_a2(root: root);
      expect(
        violations,
        contains('The repository root declares no `workspace:` block.'),
      );
      expect(
        violations,
        contains('The workspace does not list packages/zuraffa_ffi.'),
      );
      expect(violations, contains('The workspace has no shared lockfile.'));
      expect(
        violations,
        contains(
          'zuraffa_ffi_macos carries its own lockfile — the workspace must '
          'share one.',
        ),
      );
      expect(
        violations,
        contains(
          'zuraffa_ffi_macos carries its own package configuration — the '
          'workspace must share one.',
        ),
      );
    });
  });
}

// HAND-IMPLEMENTED SUBJECT — behavior A2 (zfa:tdd: A2:hand).
//
// behavior_id: A2
// source_criterion: AC-2
// description: all five family packages resolve through one pub workspace, with one shared lockfile and one shared package configuration.
//
// The scenario reads the repository's own workspace state — the root
// pubspec's `workspace:` block, the shared lockfile, and the absence of a
// per-member lockfile or package configuration.
//
// The [root] seam lets a test drive the scenario against a deliberately
// broken workspace tree, so the failure paths are covered too and not only
// the happy path.
//
// ignore_for_file: non_constant_identifier_names
library;

import 'dart:io';

import 'family_manifest.dart';

/// Scenario runner for behavior A2.
///
/// Returns the violations found; an empty list means the scenario holds.
///
/// When [root] is given it replaces the repository root the scenario reads.
List<String> subject_a2({Directory? root}) {
  final violations = <String>[];
  final workspaceRoot = root ?? repositoryRoot();

  final rootPubspec =
      File('${workspaceRoot.path}/pubspec.yaml').readAsStringSync();
  final workspaceBlock = RegExp(r'^workspace:\s*$', multiLine: true);
  if (!workspaceBlock.hasMatch(rootPubspec)) {
    violations.add('The repository root declares no `workspace:` block.');
  }
  for (final package in familyPackages) {
    if (!rootPubspec.contains('packages/$package')) {
      violations.add('The workspace does not list packages/$package.');
    }
  }

  if (!File('${workspaceRoot.path}/pubspec.lock').existsSync()) {
    violations.add('The workspace has no shared lockfile.');
  }

  for (final package in familyPackages) {
    final dir = Directory('${workspaceRoot.path}/packages/$package');
    if (File('${dir.path}/pubspec.lock').existsSync()) {
      violations.add(
        '$package carries its own lockfile — the workspace must share one.',
      );
    }
    if (File('${dir.path}/.dart_tool/package_config.json').existsSync()) {
      violations.add(
        '$package carries its own package configuration — the workspace must share one.',
      );
    }
  }

  return violations;
}
